parameters.jsCode:
const r = $input.first().json;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const rnd = (Math.random() * 16) | 0;
    const v = c === 'x' ? rnd : (rnd & 0x3) | 0x8;
    return v.toString(16);
  });
}

const counts = r.counts || {};
const errorMsg = r.error || `status=${r.status}`;
const incident_key = `google-enrichment:failed:${r.run_id || 'unknown'}`;

return [
  {
    json: {
      incident_id: uuidv4(),
      incident_key,
      severity: counts.error > 0 ? 'high' : 'medium',
      source: 'n8n-google-enrichment',
      step: 'google-enrichment',
      timestamp: new Date().toISOString(),
      summary: 'Google enrichment run failed or returned non-success status',
      error: errorMsg,
      context: {
        step: 'google-enrichment',
        run_id: r.run_id,
        pipeline_run_id: r.id,
        status: r.status,
        counts,
        provider: counts.provider,
        provider_fallback_used: counts.provider_fallback_used,
      },
    },
  },
];
